end

---列表处理
function LimitedTimeContinuousGiftDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local luaIndex = index + 1
    local cell = listView:NewListViewItem("OverseaContinuousRechargeLimitGiftCell")
    local data = self:GetProducts()[luaIndex]

    local scr = CfUtils.GetLuaScr(cell, "Game.UI.LimitedTimeContinuousGift.LimitedTimeContinuousGiftCell")
    if scr then
        scr:RefreshCell(data, luaIndex, self:GetCurrentGiftIdx(), #self:GetProducts(), Bind(self, self.CellOnClickHandler))
    end

    return cell
end

---购买点击回调
function LimitedTimeContinuousGiftDialog:CellOnClickHandler(index, scr)
    local currentGiftIdx = self:GetCurrentGiftIdx()
    if currentGiftIdx ~= index then
        GameUtils.Toast(localize('请先解锁前置礼包'))
        return
    end

    local product = self:GetProducts()[index]
    local data = ActivityMgr:GetPayTimeChestData()
    if product.isFree == 1 then
        -- 免费购买
        GameUtils.Request(Interfaces.ActivityPayTimeLimitFreeBuy, { activityUuid = data.activityUuid, productId = product.productId }, Bind(self, self.FreeBuyResponseHandler, scr))
    else
        if checkInt(product.price) > 0 then
            -- 直充
            SDKService:GetInstance():PayMoney({
                productId = product.productId,
                channelProductId = product.channelProductId,
                productDesc = localize('礼包'),
                payAmount = checkNumber(product.price),
                data = product
            })
        else
            -- 道具
            local consume = checkTable(product.consume)
            local _, errTip = GoodsUtils.CheckGoodConsume(consume)
            if errTip then
                if checkInt(consume[1].goodsId) == Constants.Currency.PayDiamondId then
                    local productVo = GoodsConfMgr:GetGoodsVoById(consume[1].goodsId)
                    ServerDifferenceMgr:WrapPrimaryCurrencyBuy({ currency = checkInt(consume[1].goodsId), current = checkInt(consume[1].num), productName = productVo.name })
                else
                    GameUtils.Toast(errTip)
                end
                return
            end
            GameUtils.Request(Interfaces.ActivityPayTimeLimitBuy, { activityUuid = data.activityUuid, productId = product.productId }, Bind(self, self.BuyResponseHandler, scr))
        end
    end
end

---免费购买response处理
function LimitedTimeContinuousGiftDialog:FreeBuyResponseHandler(scr, request, response)
    if checkNumber(response.errCode) ~= 0 then
        return
    end

    if scr then
        CfUtils.StartCoroutineWithBlocker(function()
            scr:PlayBuyAnim()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
            local responseData = checkTable(response.data)
            if #responseData.rewards > 0 then
                GoodsUtils.DrawRewards(responseData.rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards, cb = function()
                    self:InitData()
                end } })
            else
                self:InitData()
            end
        end)
    else
        local responseData = checkTable(response.data)
        if #responseData.rewards > 0 then
            GoodsUtils.DrawRewards(responseData.rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards, cb = function()
                self:InitData()
            end } })
        else
            self:InitData()
        end
    end
end

---购买response处理
function LimitedTimeContinuousGiftDialog:BuyResponseHandler(scr, request, response)
    if checkNumber(response.errCode) ~= 0 then
        return
    end

    local product = self:GetProducts()[self:GetCurrentGiftIdx()]
    local consume = checkTable(product.consume)
    for i, v in ipairs(consume) do
        v.num = -v.num
    end
    GoodsUtils.DrawRewards(consume)

    if scr then
        CfUtils.StartCoroutineWithBlocker(function()
            scr:PlayBuyAnim()
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.3))
            local responseData = checkTable(response.data)
            if #responseData.rewards > 0 then
                GoodsUtils.DrawRewards(responseData.rewards)
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards, cb = function()
                    self:InitData()
                end } })
            else
                self:InitData()
            end

        end)
    else
        local responseData = checkTable(response.data)
        if #responseData.rewards > 0 then
            GoodsUtils.DrawRewards(responseData.rewards)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = responseData.rewards, cb = function()
                self:InitData()
            end } })
        else
            self:InitData()
        end

    end
end
