--region private
---刷新界面
function LimitedTimeContinuousGiftDialog:RefreshView()
    local bgPath = string.format("Arts/Textures/RechargeLimitGift/continuous_gift_bg_%d.png", checkInt(self._activityData.activityConf.prefab))
    local imgBg = self.ScrollView.transform.parent:Find("ImgBg")
    CfUtils.FillImage(imgBg, bgPath)
    self:RefreshDisCount()
    self:RefreshCountdown()
    self:RefreshList()
    self:CheckEnd()
end

---刷新折扣
function LimitedTimeContinuousGiftDialog:RefreshDisCount()
    local activityConf = self:GetActivityConf()
    CfUtils.FillText(self.TextNumber, string.format('%d<size=52>%%</size>', tonumber(activityConf.discount) * 100))
end

---开启定时器
function LimitedTimeContinuousGiftDialog:StartTimer()
    self:StopTimer()
    TimerModule.Instance:AddTimer(Constants.TimerName.LimitedTimeContinuousGiftDialogTimer, 0, 1, function()
        local activityData = self:GetActivityData()
        if next(activityData) then
            activityData.endTime = checkInt(activityData.endTime) - 1
            if activityData.endTime <= 0 then
                CfUtils.StartCoroutineWithBlocker(function()
                    CfUtils.PlayAnimation(self.Root, "OverseaContinuousRechargeLimitGiftDialog_Out")
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.2))
                    cs_coroutine.yield_return(UIModule.BackDialog())
                end)
            else
                self:RefreshCountdown()
            end
        end
    end)
end

---停止定时器
function LimitedTimeContinuousGiftDialog:StopTimer()
    TimerModule.Instance:RemoveTimer(Constants.TimerName.LimitedTimeContinuousGiftDialogTimer)
end

---刷新倒计时
function LimitedTimeContinuousGiftDialog:RefreshCountdown()
    local activityData = self:GetActivityData()
    local endTime = checkInt(activityData.endTime)
    if endTime > 0 then
        CfUtils.FillText(self.TextTime, CfUtils.GetTimeHMS2(endTime))
    else
        CfUtils.FillText(self.TextTime, '00:00:00')
    end
end

---刷新列表
function LimitedTimeContinuousGiftDialog:RefreshList()
    local products = self:GetProducts()
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitListView(#products, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.ScrollView, #products)
    end
    local idx = self:GetCurrentGiftIdx() - 1
    self.ScrollView:MovePanelToItemIndex(idx)
end

---检查是否全部购买
function LimitedTimeContinuousGiftDialog:CheckEnd()
    if self:GetCurrentProductId() == 0 then
        UIModule.BackDialog()
    end
end
--endregion private

--region get / set
---设置活动数据
function LimitedTimeContinuousGiftDialog:SetActivityData(activityData)
    -- 排序
    table.sort(checkTable(activityData.products), function(a, b)
        return checkInt(a.pos) < checkInt(b.pos)
    end)
    self._activityData = checkTable(activityData)
end

---获取活动数据
function LimitedTimeContinuousGiftDialog:GetActivityData()
    return self._activityData
end

---获取活动配置
function LimitedTimeContinuousGiftDialog:GetActivityConf()
    return checkTable(self:GetActivityData().activityConf)
end

---获取商品
function LimitedTimeContinuousGiftDialog:GetProducts()
    return checkTable(self:GetActivityData().product)
end

---获取当前礼包index
function LimitedTimeContinuousGiftDialog:GetCurrentGiftIdx()
    local currentProductId = self:GetCurrentProductId()
    local products = self:GetProducts()
    for i, v in ipairs(products) do
        if checkInt(v.productId) == currentProductId then
            return i
        end
    end
    return #products
end

---获取当前礼包id
function LimitedTimeContinuousGiftDialog:GetCurrentProductId()
    return checkInt(self:GetActivityData().currentProductId)
end
--endregion get / set
return LimitedTimeContinuousGiftDialog